#include <QtWidgets>
#include <QTemporaryDir>
#include <cmath>
#include <complex>
#include <vector>
#include <algorithm>
#include <stdexcept>

quint32 le(const QByteArray&b,int p,int n){if(p<0||p+n>b.size())throw std::runtime_error("Truncated WAV");quint32 v=0;for(int i=0;i<n;i++)v|=quint32(quint8(b[p+i]))<<(8*i);return v;}
std::vector<double>samples(const QByteArray&b){if(b.size()<12||b.mid(0,4)!="RIFF"||b.mid(8,4)!="WAVE")throw std::runtime_error("Not RIFF/WAVE");int channels=0,bits=0;QByteArray data;for(int p=12;p+8<=b.size();){quint32 n=le(b,p+4,4);if(n>quint32(b.size()-p-8))throw std::runtime_error("Invalid WAV chunk");if(b.mid(p,4)=="fmt "){if(n<16||le(b,p+8,2)!=1)throw std::runtime_error("PCM required");channels=int(le(b,p+10,2));bits=int(le(b,p+22,2));}if(b.mid(p,4)=="data")data=b.mid(p+8,n);p+=8+int(n)+(n%2);}if(bits!=16||channels<1||channels>2||data.isEmpty())throw std::runtime_error("Use 16-bit mono/stereo PCM");std::vector<double>out;for(int i=0;i+2*channels<=data.size()&&out.size()<4096;i+=2*channels){double sum=0;for(int c=0;c<channels;c++)sum+=qint16(le(data,i+c*2,2))/32768.;out.push_back(sum/channels);}return out;}
std::vector<double>spectrum(const std::vector<double>&s){std::vector<double>out(256);if(s.size()<2)throw std::runtime_error("Too few samples");for(int k=0;k<256;k++){std::complex<double>sum=0.;for(size_t i=0;i<s.size();i++){double window=.5-.5*std::cos(6.283185307*i/(s.size()-1));double angle=-6.283185307*k*i/512.;sum+=s[i]*window*std::complex<double>(std::cos(angle),std::sin(angle));}out[k]=std::abs(sum)/s.size();}return out;}
QImage make(const QString&path){QFile f(path);if(!f.open(QIODevice::ReadOnly)||f.size()>32*1024*1024)throw std::runtime_error("Unreadable or >32 MiB file");auto spec=spectrum(samples(f.readAll()));QImage image(1024,500,QImage::Format_RGB32);image.fill(QColor("#122336"));QPainter p(&image);p.setPen(QColor("#74dfbb"));for(int k=0;k<256;k++){int h=qBound(0,int((std::log10(spec[k]+1e-6)+6)/6*450),450);p.drawLine(k*4,480,k*4,480-h);}return image;}
bool test(){std::vector<double>s(512);for(int i=0;i<512;i++)s[i]=std::sin(6.283185307*12*i/512);auto v=spectrum(s);int peak=int(std::max_element(v.begin(),v.end())-v.begin());if(peak!=12)return false;try{samples("bad");return false;}catch(const std::exception&){}return true;}

int main(int argc,char**argv){if(argc==2&&QString(argv[1])=="--self-test"){QCoreApplication a(argc,argv);return test()?0:1;}QApplication a(argc,argv);QWidget w;w.setWindowTitle("Wave Spectrum Lab");w.resize(1000,750);auto layout=new QVBoxLayout(&w);layout->addWidget(new QLabel("Analyze PCM mono/stereo WAV samples. First 4096 samples; logarithmic magnitude display."));auto controls=new QHBoxLayout;auto input=new QLineEdit;input->setPlaceholderText("Path to 16-bit PCM WAV");controls->addWidget(input);auto render=new QPushButton("Render / analyze");controls->addWidget(render);auto save=new QPushButton("Export PNG");controls->addWidget(save);layout->addLayout(controls);auto view=new QLabel;view->setAlignment(Qt::AlignCenter);layout->addWidget(view,1);QImage image;QObject::connect(render,&QPushButton::clicked,[&](){try{image=make(input->text());view->setPixmap(QPixmap::fromImage(image).scaled(920,600,Qt::KeepAspectRatio));}catch(const std::exception&e){QMessageBox::warning(&w,"Input",e.what());}});QObject::connect(save,&QPushButton::clicked,[&](){if(image.isNull())return;auto p=QFileDialog::getSaveFileName(&w,"Export image",{},"PNG (*.png)");if(!p.isEmpty()&&!image.save(p,"PNG"))QMessageBox::warning(&w,"Export","Write failed");});w.show();return a.exec();}
